#include "DHTesp.h"

const int DHT_PIN = 4;       // the DHT22 data wire is on GPIO 4
DHTesp dht;

void setup() {
  Serial.begin(115200);
  dht.setup(DHT_PIN, DHTesp::DHT22);
}

void loop() {
  TempAndHumidity d = dht.getTempAndHumidity();
  if (dht.getStatus() == DHTesp::ERROR_NONE) {
    Serial.printf("%.1f C, %.0f %% humidity\n", d.temperature, d.humidity);
  } else {
    Serial.println(dht.getStatusString());   // says what went wrong
  }
  delay(2000);               // a DHT22 can only be read every 2 seconds
}

// Add to the sketch above: const int LDR_PIN = 34;  (an ADC1 pin)
void loop() {
  TempAndHumidity d = dht.getTempAndHumidity();
  int light = analogRead(LDR_PIN);        // 0 to 4095

  if (dht.getStatus() == DHTesp::ERROR_NONE) {
    // one line per reading: seconds, temperature, humidity, light
    Serial.printf("%lu,%.1f,%.0f,%d\n",
                  millis() / 1000, d.temperature, d.humidity, light);
    if (d.temperature > 35) Serial.println("# ALERT: hot");
  }
  delay(2000);
}
